window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5e8d4215c141cb84"]={"versions": [{"id": "FIG-5e8d4215c141cb84", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstrukturdiagramm im Kontext der AUTOSAR E2E Library (End-to-End Communication Protection Library). Das Diagramm spezifiziert die statische Konfigurationsdatenstruktur für das E2E-Profil 5 (<code>E2E Profile 5 configuration</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Qualifizierter Typname: <code>E2E_P05Types::E2E_P05ConfigType</code></li>\n<li>Attribute der Struktur:</li>\n<li><code>+ DataID :uint16</code> – Eindeutige Kennung des Datenelements bzw. der E2E-Kommunikationsbeziehung.</li>\n<li><code>+ DataLength :uint16</code> – Länge der zu schützenden Daten in Bits.</li>\n<li><code>+ MaxDeltaCounter :uint8</code> – Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Zählerständen.</li>\n<li><code>+ Offset :uint16</code> – Bit-Offset des E2E-Headers innerhalb des Datenstroms bzw. Datenarrays.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Reines statisches Datenstrukturdiagramm. Es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt. Die Instanz der Konfigurationsstruktur wird typischerweise zur Initialisierung und Laufzeitkonfiguration an E2E-Profil-5-Prüf- und Schutzfunktionen übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des C-Typs bzw. der Datenstruktur <code>E2E_P05ConfigType</code> für AUTOSAR E2E Profile 5. Entwickler von Sender- und Empfänger-Softwarekomponenten oder BSW-Modulen müssen die vier Member <code>DataID</code>, <code>DataLength</code>, <code>MaxDeltaCounter</code> und <code>Offset</code> exakt mit den spezifizierten Datentypen (<code>uint16</code>, <code>uint8</code>) bereitstellen und konfigurieren.</p>"}, {"id": "FIG-148b12258219b118", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstrukturdiagramm im Kontext der AUTOSAR E2E Library (End-to-End Communication Protection Library). Das Diagramm spezifiziert die statische Konfigurationsdatenstruktur für das E2E-Profil 5 (<code>E2E Profile 5 configuration</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Qualifizierter Typname: <code>E2E::E2E_P05Types::E2E_P05ConfigType</code></li>\n<li>Attribute der Struktur:</li>\n<li><code>+ DataID :uint16</code> – Eindeutige Kennung des Datenelements bzw. der E2E-Kommunikationsbeziehung.</li>\n<li><code>+ DataLength :uint16</code> – Länge der zu schützenden Daten in Bits.</li>\n<li><code>+ MaxDeltaCounter :uint8</code> – Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Zählerständen.</li>\n<li><code>+ Offset :uint16</code> – Bit-Offset des E2E-Headers innerhalb des Datenstroms bzw. Datenarrays.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Reines statisches Datenstrukturdiagramm. Es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt. Die Instanz der Konfigurationsstruktur wird typischerweise zur Initialisierung und Laufzeitkonfiguration an E2E-Profil-5-Prüf- und Schutzfunktionen übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des C-Typs bzw. der Datenstruktur <code>E2E_P05ConfigType</code> für AUTOSAR E2E Profile 5. Entwickler von Sender- und Empfänger-Softwarekomponenten oder BSW-Modulen müssen die vier Member <code>DataID</code>, <code>DataLength</code>, <code>MaxDeltaCounter</code> und <code>Offset</code> exakt mit den spezifizierten Datentypen (<code>uint16</code>, <code>uint8</code>) bereitstellen und konfigurieren.</p>"}, {"id": "FIG-5c374c4cba05adaf", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstrukturdiagramm im Kontext der AUTOSAR E2E Library (End-to-End Communication Protection Library). Das Diagramm spezifiziert die statische Konfigurationsdatenstruktur für das E2E-Profil 5 (<code>E2E Profile 5 configuration</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine einzelne Datenstruktur (<code>«structure»</code>):</p>\n<ul class=\"fig-list\">\n<li>Qualifizierter Typname: <code>E2E_P05Types::E2E_P05ConfigType</code></li>\n<li>Attribute der Struktur:</li>\n<li><code>+ DataID: uint16</code> – Eindeutige Kennung des Datenelements bzw. der E2E-Kommunikationsbeziehung.</li>\n<li><code>+ DataLength: uint16</code> – Länge der zu schützenden Daten in Bits.</li>\n<li><code>+ MaxDeltaCounter: uint8</code> – Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Zählerständen.</li>\n<li><code>+ Offset: uint16</code> – Bit-Offset des E2E-Headers innerhalb des Datenstroms bzw. Datenarrays.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Reines statisches Datenstrukturdiagramm. Es sind keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe dargestellt. Die Instanz der Konfigurationsstruktur wird typischerweise zur Initialisierung und Laufzeitkonfiguration an E2E-Profil-5-Prüf- und Schutzfunktionen übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Definition des C-Typs bzw. der Datenstruktur <code>E2E_P05ConfigType</code> für AUTOSAR E2E Profile 5. Entwickler von Sender- und Empfänger-Softwarekomponenten oder BSW-Modulen müssen die vier Member <code>DataID</code>, <code>DataLength</code>, <code>MaxDeltaCounter</code> und <code>Offset</code> exakt mit den spezifizierten Datentypen (<code>uint16</code>, <code>uint8</code>) bereitstellen und konfigurieren.</p>"}], "trans": [{"from": "FIG-5e8d4215c141cb84", "to": "FIG-148b12258219b118", "fr": "R4.2.2", "tr": "R4.3.1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Paket-/Namespace-Pfad des Stereotyps bzw. der Datenstruktur: <code>E2E_P05Types::</code> wurde zu <code>E2E::E2E_P05Types::</code> erweitert.</li>\n</ul>"}, {"from": "FIG-148b12258219b118", "to": "FIG-5c374c4cba05adaf", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Paket-/Namespace-Pfad des Typs: <code>E2E::E2E_P05Types::</code> wurde zu <code>E2E_P05Types::</code> verkürzt.</li>\n<li>Typdeklarationssyntax der Attribute: Leerzeichen vor dem Doppelpunkt entfallen (<code>DataID: uint16</code>, <code>DataLength: uint16</code>, <code>MaxDeltaCounter: uint8</code>, <code>Offset: uint16</code> statt zuvor Leerzeichen vor dem Doppelpunkt).</li>\n</ul>"}]};
